<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use App\Models\{Commune,Locality,User,WaterPoint,TechnicianProfile,Incident,Intervention,Maintenance};
class DatabaseSeeder extends Seeder {
 public function run():void {
 if(!app()->environment('local','testing') || strlen(env('DEMO_PASSWORD',''))<12)throw new \RuntimeException('Démonstration uniquement en local/testing avec DEMO_PASSWORD de 12 caractères minimum.');
 $c=Commune::firstOrCreate(['name'=>'Commune pilote (fictive)']);$other=Commune::firstOrCreate(['name'=>'Commune voisine (fictive)']);
 $users=[];foreach(['admin'=>'Coordination pilote','gestionnaire'=>'Gestionnaire communal','relais'=>'Relais communautaire','technicien'=>'Aïcha — technicienne','usager'=>'Responsable d’école'] as $role=>$name)$users[$role]=User::firstOrCreate(['email'=>$role.'@eaurelais.test'],['name'=>$name,'password'=>env('DEMO_PASSWORD'),'role'=>$role,'commune_id'=>$c->id]);
 $profile=TechnicianProfile::firstOrCreate(['user_id'=>$users['technicien']->id],['phone'=>'+229 01 00 00 00 00','skills'=>['Pompes manuelles','Forages','Diagnostic hydraulique'],'referenced'=>true]);$profile->zones()->syncWithoutDetaching([$c->id]);
 $second=User::firstOrCreate(['email'=>'technicien2@eaurelais.test'],['name'=>'Koffi — technicien fictif','password'=>env('DEMO_PASSWORD'),'role'=>'technicien','commune_id'=>$c->id]);$sp=TechnicianProfile::firstOrCreate(['user_id'=>$second->id],['phone'=>'+229 01 00 00 00 01','skills'=>['Motorisation','Réseaux de distribution'],'referenced'=>true,'availability'=>'occupe']);$sp->zones()->syncWithoutDetaching([$c->id]);
 $names=['École Les Sources','Forage du marché','Pompe du quartier Est','Borne du centre','École Horizon','Forage des jardins'];
 foreach($names as $n=>$name){$l=Locality::firstOrCreate(['commune_id'=>$c->id,'name'=>['Village Lumière','Quartier des Jardins','Village Espoir'][$n%3]]);$p=WaterPoint::firstOrCreate(['code'=>'DEMO-0'.($n+1)],['name'=>$name.' (fictif)','locality_id'=>$l->id,'manager_id'=>$users['gestionnaire']->id,'equipment'=>$n%2?'Forage motorisé':'Pompe manuelle','community'=>$n%2?'Communauté':'École','state'=>['hors_service','degrade','fonctionnel','inconnu','hors_service','fonctionnel'][$n],'state_updated_at'=>now()]);
 $status=['signale','planifie','confirme','verification','repare','verification'][$n];
 $i=Incident::firstOrCreate(['reference'=>'EAU-DEMO-00'.($n+1)],['client_uuid'=>(string)Str::uuid(),'tracking_hash'=>Hash::make(Str::random(48)),'water_point_id'=>$p->id,'locality_id'=>$l->id,'created_by'=>$users['relais']->id,'reporter_user_id'=>$users['usager']->id,'reporter_name'=>'Déclarant fictif','phone'=>'+229 01 00 00 00 00','relationship'=>'ecole','problem'=>$n%2?'debit':'pompe','description'=>['La pompe ne permet plus de puiser de l’eau depuis ce matin.','Le débit est faible et une pièce doit être remplacée.','La réparation a été vérifiée par le relais communautaire.','La pompe présente une panne récurrente à diagnostiquer.','La réparation est terminée, la confirmation est attendue.','La panne a été rouverte après une première réparation.'][$n],'observed_at'=>today()->subDays(8-$n),'status'=>$status,'blocker'=>$n===1?'Attente de pièce de rechange':null,'created_at'=>now()->subDays(8-$n),'first_response_at'=>$n?now()->subDays(7-$n):null,'confirmed_at'=>$status==='confirme'?now()->subDays(2):null]);
 if(!$i->histories()->exists()){$i->histories()->create(['to_status'=>'signale','comment'=>'Donnée de démonstration fictive.','created_at'=>$i->created_at]);if($n===5){$i->histories()->create(['from_status'=>'planifie','to_status'=>'repare','actor_id'=>$users['technicien']->id,'comment'=>'Première réparation fictive.']);$i->histories()->create(['from_status'=>'repare','to_status'=>'verification','actor_id'=>$users['relais']->id,'comment'=>'Réouverture : le problème persiste après les essais.']);}if($status!=='signale'&&$n!==5)$i->histories()->create(['from_status'=>'signale','to_status'=>$status,'actor_id'=>$users['gestionnaire']->id,'comment'=>'Évolution fictive pour présentation.']);}
 if(in_array($status,['planifie','repare','confirme']))Intervention::firstOrCreate(['incident_id'=>$i->id,'technician_id'=>$users['technicien']->id],['scheduled_at'=>today()->addDay(),'acceptance'=>'acceptee','performed_at'=>in_array($status,['repare','confirme'])?today():null,'diagnosis'=>'Joint et mécanisme à contrôler.','work_done'=>in_array($status,['repare','confirme'])?'Joint remplacé et essais effectués.':null,'blocker'=>$n===1?'Attente de joint':null,'estimated_cost'=>25000]);
 Maintenance::firstOrCreate(['water_point_id'=>$p->id,'scheduled_at'=>today()->addDays($n-2)],['responsible_id'=>$users['technicien']->id,'operations'=>'Contrôler le mécanisme, les joints et le débit.']);
 }
 }
}
